/* @autogenerated */
import { User } from 'app/features/identity/user/model/user.model';
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { UserRepository } from 'app/features/identity/user/repository/user-repository.service';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de user: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'user-view-bulk-edit-action', standalone: false, template: '' })
export class UserViewBulkEditActionComponent extends BaseBulkEditAction<User> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'identity/user';
  protected readonly repository = inject(UserRepository);

  protected override keyOf(item: User): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<User>[] {
    return [
      { name: 'name', label: this.text('fieldName'), type: 'text' },
      { name: 'email', label: this.text('fieldEmail'), type: 'text', optional: true },
      { name: 'temporalPassword', label: this.text('fieldTemporalPassword'), type: 'boolean', optional: true },
      { name: 'useSecondFactors', label: this.text('fieldUseSecondFactors'), type: 'boolean', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<User> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
